-- Crop Database SQL import file
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS crops (
  "crop_id" TEXT,
  "crop_name" TEXT,
  "scientific_name" TEXT,
  "crop_group" TEXT,
  "record_type" TEXT,
  "common_uses" TEXT,
  "growth_cycle_days" TEXT,
  "optimal_temp_min_c" TEXT,
  "optimal_temp_max_c" TEXT,
  "annual_rainfall_min_mm" TEXT,
  "annual_rainfall_max_mm" TEXT,
  "soil_ph_min" TEXT,
  "soil_ph_max" TEXT,
  "water_requirement" TEXT,
  "planting_season" TEXT,
  "harvest_season" TEXT,
  "nasa_monitoring_variables" TEXT,
  "nasa_data_sources" TEXT,
  "agronomy_reference" TEXT,
  "agronomy_reference_url" TEXT,
  "data_quality_note" TEXT
);

